"""Build the Finance Portal page (investments/index.html) with David's NVDA chart.
Data: Yahoo chart API JSON in /tmp (nvda-daily.json, nvda-1d.json, nvda-5d.json).
"""
import json, datetime, pathlib

OUT = pathlib.Path('/home/hatch/workspace/investments/index.html')

def load(f):
    d = json.load(open(f'/tmp/{f}'))['chart']['result'][0]
    ts = d['timestamp']; q = d['indicators']['quote'][0]
    rows = []
    for i, t in enumerate(ts):
        c = q['close'][i]
        if c is None: continue
        v = q['volume'][i] if 'volume' in q and q['volume'][i] else 0
        rows.append([t * 1000, round(c, 2), int(v)])
    return rows, d['meta']

daily, meta = load('nvda-daily.json')
d1, _ = load('nvda-1d.json')
d5, _ = load('nvda-5d.json')
d1 = [[r[0], r[1]] for r in d1]
d5 = [[r[0], r[1]] for r in d5]

last_price = daily[-1][1]
today_str = datetime.datetime.now().strftime('%a · %b %-d, %Y')

DATA = json.dumps({'daily': daily, 'd1': d1, 'd5': d5}, separators=(',', ':'))

